PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, role TEXT NOT NULL CHECK(role IN ('Organizer','Attendee','Vendor','Staff')), password_hash TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, date TEXT NOT NULL, time TEXT NOT NULL, venue TEXT NOT NULL, capacity INTEGER NOT NULL CHECK(capacity>0), event_type TEXT NOT NULL DEFAULT 'Workshop', status TEXT NOT NULL DEFAULT 'Planning', budget REAL NOT NULL DEFAULT 0, description TEXT DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS resources (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, category TEXT NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>=0), available INTEGER NOT NULL CHECK(available>=0), unit TEXT NOT NULL DEFAULT 'units', location TEXT DEFAULT '', status TEXT NOT NULL DEFAULT 'Available', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS attendees (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, email TEXT NOT NULL, phone TEXT DEFAULT '', organization TEXT DEFAULT '', role TEXT DEFAULT 'Attendee', created_at TEXT NOT NULL, UNIQUE(email));
CREATE TABLE IF NOT EXISTS vendors (id INTEGER PRIMARY KEY AUTOINCREMENT, company_name TEXT NOT NULL, contact_name TEXT NOT NULL, email TEXT DEFAULT '', phone TEXT DEFAULT '', category TEXT DEFAULT 'General', status TEXT NOT NULL DEFAULT 'Onboarding', contract_value REAL NOT NULL DEFAULT 0, service TEXT DEFAULT '', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS registrations (id INTEGER PRIMARY KEY AUTOINCREMENT, event_id INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE, attendee_id INTEGER NOT NULL REFERENCES attendees(id) ON DELETE CASCADE, ticket_code TEXT NOT NULL UNIQUE, qr_token TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'Confirmed', checked_in INTEGER NOT NULL DEFAULT 0 CHECK(checked_in IN (0,1)), registered_at TEXT NOT NULL, checked_in_at TEXT, UNIQUE(event_id,attendee_id));
CREATE TABLE IF NOT EXISTS allocations (id INTEGER PRIMARY KEY AUTOINCREMENT, event_id INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE, resource_id INTEGER NOT NULL REFERENCES resources(id) ON DELETE CASCADE, quantity INTEGER NOT NULL CHECK(quantity>0), status TEXT NOT NULL DEFAULT 'Allocated', allocated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS budgets (id INTEGER PRIMARY KEY AUTOINCREMENT, event_id INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE, category TEXT NOT NULL DEFAULT 'General', amount REAL NOT NULL CHECK(amount>=0), notes TEXT DEFAULT '', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS vendors_assignments (id INTEGER PRIMARY KEY AUTOINCREMENT, event_id INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE, vendor_id INTEGER NOT NULL REFERENCES vendors(id) ON DELETE CASCADE, service TEXT NOT NULL, sla_status TEXT NOT NULL DEFAULT 'Pending', assigned_at TEXT NOT NULL, UNIQUE(event_id,vendor_id,service));
CREATE TABLE IF NOT EXISTS expenses (id INTEGER PRIMARY KEY AUTOINCREMENT, event_id INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE, vendor_id INTEGER REFERENCES vendors(id) ON DELETE SET NULL, category TEXT NOT NULL DEFAULT 'General', description TEXT NOT NULL, amount REAL NOT NULL CHECK(amount>=0), expense_date TEXT NOT NULL, approval_status TEXT NOT NULL DEFAULT 'Pending', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS approvals (id INTEGER PRIMARY KEY AUTOINCREMENT, expense_id INTEGER NOT NULL REFERENCES expenses(id) ON DELETE CASCADE, approver TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Pending', comments TEXT DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER REFERENCES users(id) ON DELETE CASCADE, type TEXT NOT NULL, title TEXT NOT NULL, message TEXT NOT NULL, is_read INTEGER NOT NULL DEFAULT 0 CHECK(is_read IN (0,1)), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS workflows (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, trigger_type TEXT NOT NULL, action_type TEXT NOT NULL, condition_value TEXT DEFAULT '', is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN (0,1)), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER REFERENCES users(id) ON DELETE SET NULL, entity_type TEXT NOT NULL, entity_id INTEGER, action TEXT NOT NULL, details TEXT DEFAULT '', created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_events_date ON events(date);
CREATE INDEX IF NOT EXISTS idx_reg_event ON registrations(event_id);
CREATE INDEX IF NOT EXISTS idx_alloc_event_date ON allocations(event_id,status);
CREATE INDEX IF NOT EXISTS idx_expenses_event ON expenses(event_id);
CREATE INDEX IF NOT EXISTS idx_notifications_read ON notifications(is_read);
